examples.code:
#include <cassert>
#include <iterator>

int main() {
    int a[]{0, 1, 2, 3};
    //            ↑  └───── x, y
    //            └──────── z
    // “x” and “y” are equal, but “x” is less than “z” (reversely)
    std::reverse_iterator<int *> x{std::rend(a) - std::size(a)},
        y{std::rend(a) - std::size(a)}, z{std::rbegin(a) + 1};

    // two-way comparisons
    assert(x == y);
    assert(!(x != y));
    assert(!(x < y));
    assert(x <= y);
    assert(!(x == z));
    assert(x != z);
    assert(x < z);
    assert(x <= z);

    // three-way comparisons
    assert(x <=> y == 0);
    assert(!(x <=> y < 0));
    assert(!(x <=> y > 0));
    assert(!(x <=> z == 0));
    assert(x <=> z < 0);
    assert(!(x <=> z > 0));
}
